/* ART-ATLAS-V4 — новый визуальный слой по референсу пользователя. */
(function(){
if(window.__ART_ATLAS_V4)return;window.__ART_ATLAS_V4=true;
const SHEET='data:image/webp;base64,';
const V4_STYLE=document.createElement('style');V4_STYLE.textContent='.scene.art-v4-scene:before,.scene.art-v4-scene:after{display:none!important}.scene.art-v4-scene{background-repeat:no-repeat!important}.atlas-creature-v4{background-image:url(\"'+SHEET+'\");background-size:400% 600%;background-repeat:no-repeat;}';document.head.appendChild(V4_STYLE);const names=['shadow','hunter','mutant','bones','elite','boss','start','ordinary','treasure','shop','forge','tavern','sanctuary','cursed','library','altar','trap','labyrinth','portal','bossroom','eliteroom','event'];
const idx={};names.forEach((n,i)=>idx[n]=i);
function v4Tile(n){const i=idx[n];if(i==null)return '';return 'background-size:400% 600%;background-position:'+((i%4)*100/3)+'% '+(Math.floor(i/4)*100/5)+'%;background-repeat:no-repeat;';}
const V4_TILE_CACHE={};
let V4_SHEET_IMG=null;
function loadV4Sheet(){
if(V4_SHEET_IMG)return V4_SHEET_IMG;
const img=new Image();
img.decoding='async';
img.src=SHEET;
V4_SHEET_IMG=img;
return img;
}
function v4QualityData(key,w,h){
/* Заполняем всю область без растяжения: исходный квадрат масштабируется пропорционально, лишнее аккуратно обрезается по центру. */
const width=Math.max(1,Math.min(1024,Math.round(w||256)));
const height=Math.max(1,Math.min(1024,Math.round(h||256)));
const k=key+'@'+width+'x'+height;
if(V4_TILE_CACHE[k])return V4_TILE_CACHE[k];
const img=loadV4Sheet();
const make=function(){
try{
const dpr=Math.min(2,Math.max(1,window.devicePixelRatio||1));
const cw=Math.max(1,Math.round(width*dpr));
const ch=Math.max(1,Math.round(height*dpr));
const c=document.createElement('canvas');c.width=cw;c.height=ch;
const ctx=c.getContext('2d',{alpha:true});
if(!ctx)return null;
ctx.imageSmoothingEnabled=true;
ctx.imageSmoothingQuality='high';
const i=idx[key];if(i==null)return null;
const sx=(i%4)*256,sy=Math.floor(i/4)*256;
/* Вычисляем центральный crop так, чтобы квадратный исходник заполнил прямоугольную область без деформации. */
const targetRatio=width/height;
let sw=256,sh=256,ox=0,oy=0;
if(targetRatio>1){
sh=256/targetRatio;
oy=(256-sh)/2;
}else if(targetRatio<1){
sw=256*targetRatio;
ox=(256-sw)/2;
}
/* Один качественный ресэмплинг из исходного тайла, без промежуточного растягивания. */
ctx.filter='contrast(1.06) saturate(1.04)';
ctx.drawImage(img,sx+ox,sy+oy,sw,sh,0,0,cw,ch);
ctx.filter='none';
const data=c.toDataURL('image/png');
V4_TILE_CACHE[k]=data;
return data;
}catch(e){return null;}
};
if(img.complete&&img.naturalWidth)return make();
img.addEventListener('load',make,{once:true});
return null;
}
function renderV4Tile(el,key,w,h){
if(!el)return;
const width=Math.max(1,Math.min(1024,Math.round(w||el.clientWidth||256)));
const height=Math.max(1,Math.min(1024,Math.round(h||el.clientHeight||256)));
const data=v4QualityData(key,width,height);
if(data){
el.style.setProperty('background-image','url("'+data+'")','important');
el.style.setProperty('background-size','100% 100%','important');
el.style.setProperty('background-position','center center','important');
el.style.setProperty('background-repeat','no-repeat','important');
el.style.setProperty('image-rendering','auto','important');
el.dataset.v4QualityKey=key+'@'+width+'x'+height;
return true;
}
const img=loadV4Sheet();
const apply=function(){
if(!el.isConnected)return;
el.style.setProperty('background-image','url("'+SHEET+'")','important');
el.style.setProperty('background-size','400% auto','important');
el.style.setProperty('background-position',v4Tile(key).match(/background-position:[^;]+;/)?.[0]?.replace('background-position:','').replace(';','')||'center center','important');
el.style.setProperty('background-repeat','no-repeat','important');
el.dataset.v4QualityKey=key+'@raw';
setTimeout(function(){renderV4Tile(el,key,width,height)},0);
};
if(img.complete&&img.naturalWidth)apply();else img.addEventListener('load',apply,{once:true});
return false;
}
window.renderV4Tile=renderV4Tile;
function setScene(id,key){
const s=document.querySelector('#'+id+' .scene');if(!s)return;
const i=idx[key];if(i==null)return;
s.classList.add('art-v4-scene');
s.style.setProperty('background-repeat','no-repeat','important');
s.style.setProperty('background-position','center center','important');
s.style.setProperty('background-size','cover','important');
renderV4Tile(s,key,s.clientWidth||700,s.clientHeight||390);
}
function roomKeyV4(){const c=String(typeof abyssRoomContent!=='undefined'?abyssRoomContent:'');if(c.includes('Кровавый алтарь'))return'altar';if(c.includes('Забытый тайник'))return'treasure';if(c.includes('Источник Бездны'))return'portal';if(c.includes('Босс:'))return'bossroom';if(c.includes('Элитный враг:'))return'eliteroom';if(c.includes('Пустой проход')||c.includes('Побеждён'))return'ordinary';return'labyrinth';}
function updateScenesV4(){setScene('main','start');setScene('shop','shop');setScene('tavern','tavern');setScene('equipment','forge');setScene('stats','library');setScene('journal','ordinary');setScene('death','cursed');const a=document.getElementById('abyss');if(a&&!a.classList.contains('hidden'))setScene('abyss',roomKeyV4());}
function installBattleV4(){const old=window.updateBattle;if(typeof old!=='function'||old.__artV4)return false;function wrapped(){old.apply(this,arguments);const b=document.getElementById('enemyArt');if(!b)return;let k='shadow';if(typeof enemy!=='undefined'&&enemy){if(enemy.isBoss)k='boss';else if(enemy.isElite)k='elite';else k=({'Теневой зверь':'shadow','Заражённый охотник':'hunter','Мутант пустоши':'mutant','Пожиратель костей':'bones'})[enemy.name]||'shadow';}b.innerHTML='<span class="atlas-creature-v4" style="'+v4Tile(k)+'"></span>';const e=b.firstElementChild;if(e){e.style.display='block';e.style.width='min(86vw,300px)';e.style.height='min(86vw,220px)';e.style.margin='auto';e.style.setProperty('background-size','400% 600%','important');e.style.setProperty('background-position',((idx[k]%4)*100/3)+'% '+(Math.floor(idx[k]/4)*100/5)+'%','important');// Позиция спрайта задаётся точными координатами атласа выше.
e.style.border='1px solid rgba(45,125,170,.65)';e.style.boxShadow='0 0 22px rgba(0,70,110,.28)';}}wrapped.__artV4=true;wrapped.__battleArtRuntimeFix=true;window.updateBattle=wrapped;return true;}
function installAbyssV4(){const old=window.updateAbyss;if(typeof old!=='function'||old.__artV4)return false;function wrapped(){old.apply(this,arguments);setTimeout(updateScenesV4,0);}wrapped.__artV4=true;window.updateAbyss=wrapped;return true;}
function installScreenV4(){const old=window.setScreen;if(typeof old!=='function'||old.__artV4)return false;function wrapped(){old.apply(this,arguments);setTimeout(updateScenesV4,0);}wrapped.__artV4=true;window.setScreen=wrapped;return true;}
function bootV4(){installBattleV4();installAbyssV4();installScreenV4();updateScenesV4();}
bootV4();document.addEventListener('DOMContentLoaded',bootV4);setTimeout(bootV4,250);
})();
